import { writable, derived } from 'svelte/store';
import { createSudoku, createGame, createGameFromJSON, Game } from '@domain/index';
import { solveSudoku } from '@sudoku/sudoku';
import { grid as originalGrid } from './grid';

/**
 * Store Adapter：领域对象与 Svelte UI 之间的唯一桥梁。
 *
 * HW2：
 * - 两种提示：候选提示（getCandidatesInfo）与下一步提示（findHintCell / applyHintFill）
 * - 探索模式：独立 history + 新冲突检测 + 失败分支记忆
 */
function createGameStore() {
  /** @type {Game} */
  let _game = Game.empty();

  const _version = writable(0);
  let _skipNextGridSync = false;

  function _notify() {
    _version.update(v => v + 1);
  }

  originalGrid.subscribe($grid => {
    if (_skipNextGridSync) {
      _skipNextGridSync = false;
      return;
    }
    const hasContent = $grid.some(row => row.some(v => v !== 0));
    if (hasContent) {
      const sudoku = createSudoku($grid);
      _game = createGame({ sudoku });
      _notify();
    }
  });

  /* ========== 响应式派生状态 ========== */

  const grid = derived(_version, () => _game.getGrid());
  const initialGrid = derived(_version, () => _game.getInitialGrid());
  const invalidCells = derived(_version, () =>
    _game.findConflicts().map(c => `${c.col},${c.row}`)
  );
  const won = derived(_version, () => _game.isSolved());
  const canUndo = derived(_version, () => _game.canUndo());
  const canRedo = derived(_version, () => _game.canRedo());

  // HW2: 探索模式
  const isExploring = derived(_version, () => _game.isExploring());
  const exploreFailedBranches = derived(_version, () => _game.getFailedBranchCount());
  const exploreHasConflicts = derived(_version, () => {
    if (!_game.isExploring()) return false;
    return _game.findConflicts().length > 0;
  });

  // HW2: 提示结果（缓存最近一次 findHint 的结果）
  let _lastHint = null;

  /** 用户反馈消息 store */
  const lastMessage = writable(null); // { text: string, type: 'info' | 'warn' } | null
  let _messageTimer = null;

  function _showMessage(text, type = 'info') {
    if (_messageTimer) clearTimeout(_messageTimer);
    lastMessage.set({ text, type });
    _messageTimer = setTimeout(() => lastMessage.set(null), 4000);
  }

  /* ========== 生命周期方法 ========== */

  function startNew(puzzleGrid) {
    _skipNextGridSync = true;
    const sudoku = createSudoku(puzzleGrid);
    _game = createGame({ sudoku });
    _lastHint = null;
    _notify();
  }

  function loadFromJSON(json) {
    _game = createGameFromJSON(json);
    _lastHint = null;
    _notify();
  }

  /* ========== 操作方法 ========== */

  function guess(move) {
    // 探索模式：记录 guess 前冲突数
    if (_game.isExploring()) {
      _game.recordPreGuessState();

      // 检查目标盘面是否属于已知失败分支
      const clone = _game.getSudoku();
      const cloneResult = clone.guess(move);
      if (cloneResult.success) {
        const targetHash = clone.hashBoard();
        if (_game.isHashInFailedBranches(targetHash)) {
          _showMessage('This board state was tried before and led to failure. Try a different value.', 'warn');
          return { success: false, reason: 'This branch was previously tried and failed' };
        }
      }
    }

    const result = _game.guess(move);
    if (!result.success) {
      return result;
    }

    // 探索模式：仅当本次 guess 引入了新冲突才标记失败分支
    if (_game.isExploring() && _game.hasNewConflicts()) {
      _game.markFailedBranch();
    }

    _notify();
    return result;
  }

  function undo() {
    _game.undo();
    _notify();
  }

  function redo() {
    _game.redo();
    _notify();
  }

  /* ========== HW2：提示 — 类型 1：候选提示 ========== */

  /**
   * 获取光标所在格的候选数及解释。
   * @param {number} row
   * @param {number} col
   * @returns {{ candidates: number[], eliminated: { value: number, reason: string }[] }}
   */
  function getCandidatesInfo(row, col) {
    return _game.getSudoku().getCandidatesWithExplanation(row, col);
  }

  /* ========== HW2：提示 — 类型 2：下一步提示 ========== */

  /**
   * 查找下一步可推断的格子（仅返回位置，不自动填入）。
   * @returns {{ row: number, col: number, value: number, explanation: string } | null}
   */
  function findHintCell() {
    _lastHint = _game.findHint();
    if (!_lastHint) {
      _showMessage('No deducible cell found — all empty cells have 2+ candidates. Try Explore mode.', 'info');
    }
    return _lastHint;
  }

  /**
   * 自动填入下一步提示的值。
   * 先调用 findHint，若有结果则自动填入并消耗提示次数。
   * @returns {{ row: number, col: number, value: number } | null} 填入的提示，null 表示无可用提示
   */
  function applyHintFill() {
    const hint = _game.findHint();
    if (!hint) return null;
    _lastHint = hint;
    guess({ row: hint.row, col: hint.col, value: hint.value });
    return hint;
  }

  /**
   * 对指定格子应用提示：从原始题面求解并填入正确值。
   * @param {number} row
   * @param {number} col
   */
  function applyHintAtCell(row, col) {
    const initialGrid = _game.getInitialGrid();
    const solved = solveSudoku(initialGrid);
    const correctValue = solved[row][col];
    if (correctValue == null || correctValue === 0) return;
    guess({ row, col, value: correctValue });
  }

  /** 获取最近一次提示结果 */
  function getLastHint() {
    return _lastHint;
  }

  /* ========== HW2：探索模式 ========== */

  function beginExplore() {
    _lastHint = null;
    const result = _game.beginExplore();
    if (result.success) _notify();
    return result;
  }

  function commitExplore() {
    const result = _game.commitExplore();
    if (result.success) _notify();
    return result;
  }

  function abandonExplore() {
    const result = _game.abandonExplore();
    if (result.success) _notify();
    return result;
  }

  function backtrackExplore() {
    const result = _game.backtrackExplore();
    if (result.success) _notify();
    return result;
  }

  /* ========== 查询方法 ========== */

  function isInitialCell(row, col) {
    return _game.isInitialCell(row, col);
  }

  function toJSON() {
    return _game.toJSON();
  }

  function getGame() {
    return _game;
  }

  return {
    // 响应式状态
    grid,
    initialGrid,
    invalidCells,
    won,
    canUndo,
    canRedo,
    isExploring,
    exploreFailedBranches,
    exploreHasConflicts,

    // 生命周期
    startNew,
    loadFromJSON,

    // 操作
    guess,
    undo,
    redo,

    // 提示
    getCandidatesInfo,
    findHintCell,
    applyHintFill,
    applyHintAtCell,
    getLastHint,
    lastMessage,

    // 探索
    beginExplore,
    commitExplore,
    abandonExplore,
    backtrackExplore,

    // 查询
    isInitialCell,
    toJSON,
    getGame,
  };
}

export const gameStore = createGameStore();
